<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>HackMate - Embossed Dashboard</title>
    <style>
        :root {
            /* Palette */
            --bg-base: #0a0b0d;
            --bg-surface: rgba(20, 24, 28, 0.65);
            --border-light: rgba(255, 255, 255, 0.12);
            --border-dark: rgba(0, 0, 0, 0.6);

            /* Text */
            --text-primary: #f1f5f9;
            --text-secondary: #94a3b8;
            --accent: #10b981; /* Emerald */
            --accent-glow: rgba(16, 185, 129, 0.4);
            --danger: #ef4444;

            /* Spacing & Radius */
            --radius-sm: 6px;
            --radius-md: 12px;
            --radius-lg: 16px;
            --radius-xl: 24px;
            --space-xs: 4px;
            --space-sm: 8px;
            --space-md: 16px;
            --space-lg: 24px;
            --space-xl: 32px;

            /* Shadows (The Embossing) */
            /* Key Light from Top Left (-135deg approx) */
            --shadow-raised: 
                -3px -3px 6px rgba(255, 255, 255, 0.08), /* Highlight Top/Left */
                5px 5px 12px rgba(0, 0, 0, 0.6);         /* Shadow Bottom/Right */

            --shadow-inset: 
                inset -2px -2px 4px rgba(255, 255, 255, 0.05),
                inset 3px 3px 6px rgba(0, 0, 0, 0.7);

            --shadow-float: 
                -4px -4px 10px rgba(255, 255, 255, 0.06), 
                8px 8px 20px rgba(0, 0, 0, 0.7);
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
            outline: none;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-base);
            color: var(--text-primary);
            min-height: 100vh;
            line-height: 1.5;
            overflow-x: hidden;
            position: relative;
        }

        /* --- Background Effects (Goal 4) --- */
        .ambient-bg {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: -1;
            background: 
                radial-gradient(circle at 15% 15%, rgba(16, 185, 129, 0.08) 0%, transparent 40%),
                radial-gradient(circle at 85% 85%, rgba(59, 130, 246, 0.06) 0%, transparent 45%),
                linear-gradient(135deg, #0f1115 0%, #050608 100%);
        }

        .vignette {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: -1;
            box-shadow: inset 0 0 100px rgba(0,0,0,0.8);
            pointer-events: none;
        }

        /* --- Layout --- */
        .app-container {
            max-width: 1280px;
            margin: 0 auto;
            padding: var(--space-lg) var(--space-lg);
        }

        /* --- Components: Embossed Card (Goal 1 & 2) --- */
        .card {
            background: var(--bg-surface);
            backdrop-filter: blur(16px);
            -webkit-backdrop-filter: blur(16px);
            border-radius: var(--radius-lg);
            border: 1px solid var(--border-light);
            box-shadow: var(--shadow-raised);
            padding: var(--space-lg);
            transition: transform 0.2s ease, box-shadow 0.2s ease;
            position: relative;
            overflow: hidden;
        }

        .card:hover {
            transform: translateY(-2px);
            box-shadow: 
                -5px -5px 12px rgba(255, 255, 255, 0.1), 
                10px 10px 25px rgba(0, 0, 0, 0.7);
        }

        /* --- Header / Navbar --- */
        header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: var(--space-xl);
            padding: var(--space-sm) var(--space-md);
            background: rgba(18, 22, 26, 0.7);
            backdrop-filter: blur(20px);
            border-radius: var(--radius-xl);
            border: 1px solid var(--border-light);
            box-shadow: var(--shadow-raised);
        }

        .nav-left, .nav-right {
            display: flex;
            align-items: center;
            gap: var(--space-md);
        }

        .logo {
            font-weight: 700;
            font-size: 1.2rem;
            display: flex;
            align-items: center;
            gap: var(--space-sm);
            color: var(--text-primary);
        }

        .logo-icon {
            color: var(--accent);
            filter: drop-shadow(0 0 5px var(--accent-glow));
        }

        /* Nav Pills (Goal C) */
        .nav-pill {
            font-size: 0.85rem;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--text-secondary);
            padding: 8px 16px;
            border-radius: var(--radius-xl);
            cursor: pointer;
            border: 1px solid transparent;
            background: transparent;
            transition: all 0.2s ease;
            /* Base emboss for inactive state (subtle) */
            box-shadow: none; 
        }

        .nav-pill:hover {
            color: var(--text-primary);
            background: rgba(255,255,255,0.03);
        }

        .nav-pill.active {
            color: var(--accent);
            background: rgba(16, 185, 129, 0.1);
            border: 1px solid rgba(16, 185, 129, 0.3);
            /* Raised Pill Effect */
            box-shadow: 
                -2px -2px 5px rgba(255, 255, 255, 0.05),
                3px 3px 6px rgba(0, 0, 0, 0.4);
            text-shadow: 0 1px 2px rgba(0,0,0,0.5);
        }

        .search-bar {
            display: flex;
            align-items: center;
            background: rgba(0, 0, 0, 0.3);
            border: 1px solid var(--border-dark);
            border-radius: var(--radius-xl);
            padding: 6px 16px;
            width: 240px;
            color: var(--text-secondary);
            font-size: 0.9rem;
            box-shadow: var(--shadow-inset);
        }

        .search-bar span { margin-right: 8px; opacity: 0.7; }

        .icon-btn {
            width: 36px;
            height: 36px;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 50%;
            border: 1px solid var(--border-light);
            background: rgba(255,255,255,0.03);
            color: var(--text-secondary);
            cursor: pointer;
            box-shadow: var(--shadow-raised);
            transition: all 0.2s;
            position: relative;
        }

        .icon-btn:hover { color: var(--text-primary); transform: translateY(-1px); }

        .badge {
            position: absolute;
            top: -2px;
            right: -2px;
            width: 14px;
            height: 14px;
            background: var(--danger);
            border-radius: 50%;
            border: 2px solid var(--bg-base);
            font-size: 9px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-weight: bold;
        }

        .avatar {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            background: var(--accent);
            color: #000;
            font-weight: bold;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.8rem;
            box-shadow: var(--shadow-raised);
            border: 1px solid rgba(255,255,255,0.2);
        }

        /* --- Main Content --- */
        .page-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: var(--space-lg);
        }

        h1 { font-size: 1.75rem; font-weight: 600; letter-spacing: -0.02em; }

        .action-row {
            display: flex;
            gap: var(--space-sm);
        }

        .btn {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 10px 20px;
            border-radius: var(--radius-md);
            font-size: 0.9rem;
            font-weight: 500;
            cursor: pointer;
            border: 1px solid var(--border-light);
            background: rgba(255,255,255,0.03);
            color: var(--text-primary);
            box-shadow: var(--shadow-raised);
            transition: all 0.2s;
        }

        .btn:hover {
            transform: translateY(-1px);
            background: rgba(255,255,255,0.06);
        }

        .btn-primary {
            background: var(--accent);
            color: #021a10;
            border-color: rgba(255,255,255,0.2);
            font-weight: 700;
            box-shadow: 
                -3px -3px 8px rgba(255,255,255,0.2),
                4px 4px 10px rgba(0,0,0,0.4),
                0 0 15px var(--accent-glow);
        }
        .btn-primary:hover {
            background: #34d399;
            box-shadow: 
                -3px -3px 8px rgba(255,255,255,0.3),
                6px 6x 14px rgba(0,0,0,0.5),
                0 0 25px var(--accent-glow);
        }

        /* Search Area */
        .main-search-area {
            display: flex;
            gap: var(--space-md);
            margin-bottom: var(--space-lg);
        }

        .big-search {
            flex: 1;
            background: var(--bg-surface);
            border: 1px solid var(--border-light);
            border-radius: var(--radius-xl);
            padding: 12px 24px;
            color: var(--text-secondary);
            font-size: 0.95rem;
            box-shadow: var(--shadow-inset);
            display: flex;
            align-items: center;
        }
        .big-search input {
            background: transparent;
            border: none;
            color: var(--text-primary);
            width: 100%;
            margin-left: 12px;
        }

        /* Filter Tabs */
        .filter-tabs {
            display: flex;
            gap: var(--space-sm);
            margin-bottom: var(--space-xl);
        }

        .filter-chip {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 8px 16px;
            background: rgba(255,255,255,0.03);
            border: 1px solid var(--border-dark);
            border-radius: var(--radius-md);
            color: var(--text-secondary);
            font-size: 0.9rem;
            cursor: pointer;
            box-shadow: var(--shadow-raised);
            transition: 0.2s;
        }
        .filter-chip:hover {
            color: var(--text-primary);
            border-color: var(--border-light);
        }
        .filter-chip strong { color: var(--text-primary); }

        /* Grid */
        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(480px, 1fr));
            gap: var(--space-lg);
        }

        /* Card Internal Styles */
        .card-header {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            margin-bottom: var(--space-sm);
        }

        .tags { display: flex; gap: 6px; margin-bottom: var(--space-md); }

        .tag {
            font-size: 0.75rem;
            padding: 4px 10px;
            border-radius: 20px;
            font-weight: 600;
            border: 1px solid transparent;
            text-transform: uppercase;
            letter-spacing: 0.02em;
        }

        .tag-gray { background: rgba(255,255,255,0.08); color: var(--text-secondary); border-color: rgba(255,255,255,0.1); box-shadow: inset 1px 1px 2px rgba(0,0,0,0.2); }
        .tag-red { background: rgba(239, 68, 68, 0.15); color: #fca5a5; border-color: rgba(239, 68, 68, 0.3); }

        .prize-box {
            text-align: right;
        }
        .prize-label { font-size: 0.75rem; color: var(--text-secondary); display: block; }
        .prize-val { font-weight: 700; font-size: 1rem; color: var(--text-primary); }

        h2 { font-size: 1.35rem; margin-bottom: 6px; font-weight: 700; }
        .subtitle { color: var(--text-secondary); font-size: 0.95rem; margin-bottom: var(--space-lg); }

        .meta-row {
            display: flex;
            flex-wrap: wrap;
            gap: var(--space-md);
            color: var(--text-secondary);
            font-size: 0.85rem;
            margin-bottom: var(--space-lg);
            border-bottom: 1px solid rgba(255,255,255,0.05);
            padding-bottom: var(--space-md);
        }
        .meta-item { display: flex; align-items: center; gap: 6px; }

        .tech-stack { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: var(--space-lg); }
        .chip {
            background: rgba(255,255,255,0.05);
            padding: 6px 12px;
            border-radius: var(--radius-sm);
            font-size: 0.8rem;
            color: #cbd5e1;
            border: 1px solid rgba(255,255,255,0.05);
            box-shadow: var(--shadow-raised); /* Small embossed chips */
        }

        .card-footer {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: auto;
            padding-top: var(--space-md);
            border-top: 1px solid rgba(255,255,255,0.05);
        }

        .cta-link {
            color: var(--accent);
            text-decoration: none;
            font-size: 0.9rem;
            font-weight: 600;
            display: flex;
            align-items: center;
            gap: 6px;
            text-shadow: 0 0 10px rgba(16, 185, 129, 0.3);
        }

        .ghost-link {
            color: var(--text-secondary);
            text-decoration: none;
            font-size: 0.9rem;
            font-weight: 500;
            display: flex;
            align-items: center;
            gap: 6px;
        }
        .ghost-link:hover { color: var(--text-primary); }

        /* Icons */
        svg { fill: currentColor; width: 16px; height: 16px; }
        .icon-lg { width: 20px; height: 20px; }

        @media (max-width: 768px) {
            .grid { grid-template-columns: 1fr; }
            header { flex-wrap: wrap; gap: 10px; }
            .nav-pill:not(.active) { display: none; } /* Simplified for mobile view based on image logic */
            .search-bar { display: none; }
        }
    </style>
</head>
